function walk\(dir\) {
  const files = [];
  for \(const f of fs.readdirSync\(dir\)\) {
    const full = path.join\(dir, f\);
    if \(fs.statSync\(full\).isDirectory\(\)\) files.push\(...walk\(full\)\);
